app.get('/api/catalog',async(req,res,next)=>{try{const values=[],where=[`p.status='active'`];const add=(sql,value)=>{values.push(value);where.push(sql.replace('?',`$${values.length}`))};if(req.query.size&&req.query.size!=='all')add(`EXISTS(SELECT 1 FROM product_variants vf WHERE vf.colorway_id=cw.id AND vf.active AND vf.size=? AND vf.stock_on_hand>vf.reserved_stock)`,req.query.size);if(req.query.available==='true')where.push('EXISTS(SELECT 1 FROM product_variants va WHERE va.colorway_id=cw.id AND va.active AND va.stock_on_hand>va.reserved_stock)');if(req.query.customizable==='true')where.push('p.customizable AND EXISTS(SELECT 1 FROM product_customization_options pco WHERE pco.product_id=p.id AND pco.enabled)');const sort={featured:'p.featured DESC,p.sort_order,cw.sort_order,p.created_at DESC',newest:'p.created_at DESC,cw.sort_order',price_asc:'p.base_price ASC,p.sort_order,cw.sort_order',price_desc:'p.base_price DESC,p.sort_order,cw.sort_order',rating:'p.rating_average DESC,p.approved_review_count DESC,p.sort_order,cw.sort_order'}[req.query.sort]||'p.featured DESC,p.sort_order,cw.sort_order,p.created_at DESC';const limit=Math.min(24,Math.max(1,Number(req.query.limit)||12)),offset=Math.max(0,Number(req.query.cursor)||0);values.push(limit+1,offset);const result=await query(`${catalogSelect} WHERE ${where.join(' AND ')} ORDER BY ${sort},p.id,cw.id LIMIT $${values.length-1} OFFSET $${values.length}`,values);const hasMore=result.rows.length>limit,items=result.rows.slice(0,limit).map(productJson);res.json({items,nextCursor:hasMore?String(offset+limit):null,applied:{size:req.query.size||'all',sort:req.query.sort||'featured'}})}catch(error){next(error)}});
app.get('/api/products/:slug',async(req,res,next)=>{try{const product=(await query(`${productSelect} WHERE p.slug=$1 AND p.status='active'`,[req.params.slug])).rows[0];if(!product)return res.status(404).json({error:'Product not found.'});const reviews=await query(`SELECT r.id,r.rating,r.title,r.body,r.submitted_at,u.full_name,COALESCE(jsonb_agg(jsonb_build_object('url',rm.storage_key,'order',rm.sort_order)) FILTER(WHERE rm.id IS NOT NULL),'[]') media FROM reviews r JOIN users u ON u.id=r.user_id LEFT JOIN review_media rm ON rm.review_id=r.id AND rm.processing_state='ready' AND rm.moderation_state='approved' WHERE r.product_id=$1 AND r.status='approved' GROUP BY r.id,u.full_name ORDER BY r.submitted_at DESC LIMIT 12`,[product.id]);res.json({product:productJson(product),reviews:reviews.rows})}catch(error){next(error)}});

app.post('/api/auth/otp/request',rateLimit('otp',5,10*60_000,req=>`${clientIp(req)}:${phone(req.body?.phone)||'invalid'}`),async(req,res,next)=>{try{const normalized=phone(req.body?.phone);if(!normalized)return res.status(400).json({error:'Enter a valid Indian mobile number.'});const provider=String(process.env.SMS_PROVIDER||'demo').toLowerCase();if(provider==='msg91'&&!msg91Configured())return res.status(503).json({error:'MSG91 is selected but its auth key and template ID are not configured yet.'});if(!['demo','msg91'].includes(provider))return res.status(503).json({error:'Unsupported SMS provider configuration.'});const id=crypto.randomUUID();let otp='';if(provider==='msg91'){try{await msg91SendOtp(normalized)}catch(error){console.error(error);return res.status(502).json({error:'MSG91 could not send the verification code.'})}}else{const configuredDemoOtp=String(process.env.DEMO_OTP||'').replace(/\D/g,'');otp=configuredDemoOtp.length===6?configuredDemoOtp:String(crypto.randomInt(100000,1000000))}await query(`INSERT INTO otp_challenges(id,phone_e164,purpose,provider,otp_hash,expires_at) VALUES($1,$2,'login',$3,$4,now()+interval '5 minutes')`,[id,normalized,provider,hmac(`${id}:${provider==='msg91'?'remote':otp}`)]);const payload={challengeId:id,message:provider==='msg91'?'If the number is valid, a verification code has been sent by MSG91.':'Demo mode: use the verification code shown below.'};if(provider==='demo')payload.demoOtp=otp;res.status(202).json(payload)}catch(error){next(error)}});
app.post('/api/auth/otp/verify',rateLimit('verify',10,10*60_000,req=>clientIp(req)),async(req,res,next)=>{const client=await pool.connect();try{await client.query('BEGIN');const challenge=(await client.query('SELECT * FROM otp_challenges WHERE id=$1 FOR UPDATE',[req.body.challengeId])).rows[0];if(!challenge||challenge.consumed_at||new Date(challenge.expires_at)<new Date()||challenge.attempt_count>=5){await client.query('ROLLBACK');return res.status(400).json({error:'The verification code is invalid or expired.'});}await client.query('UPDATE otp_challenges SET attempt_count=attempt_count+1 WHERE id=$1',[challenge.id]);let valid=false;if(challenge.provider==='msg91'){try{valid=await msg91VerifyOtp(challenge.phone_e164,req.body.otp)}catch(error){console.error(error);valid=false}}else{const supplied=hmac(`${challenge.id}:${String(req.body.otp||'')}`);valid=crypto.timingSafeEqual(Buffer.from(supplied),Buffer.from(challenge.otp_hash))}if(!valid){await client.query('COMMIT');return res.status(400).json({error:'The verification code is invalid or expired.'})}await client.query('UPDATE otp_challenges SET consumed_at=now() WHERE id=$1',[challenge.id]);let user=(await client.query('SELECT * FROM users WHERE phone_e164=$1',[challenge.phone_e164])).rows[0],isNewUser=false;if(!user){user=(await client.query('INSERT INTO users(phone_e164,phone_verified_at,last_login_at) VALUES($1,now(),now()) RETURNING *',[challenge.phone_e164])).rows[0];isNewUser=true}else await client.query('UPDATE users SET last_login_at=now(),phone_verified_at=COALESCE(phone_verified_at,now()) WHERE id=$1',[user.id]);await client.query('INSERT INTO wallet_accounts(user_id) VALUES($1) ON CONFLICT(user_id) DO NOTHING',[user.id]);const token=randomToken(),csrf=randomToken(18),sessionHash=sha(token);await client.query(`INSERT INTO customer_sessions(user_id,session_hash,csrf_hash,expires_at) VALUES($1,$2,$3,now()+interval '30 days')`,[user.id,sessionHash,csrf]);await client.query('COMMIT');setCookie(res,'customer_session',token,2592000);res.json({user:{id:user.id,phone:user.phone_e164,fullName:user.full_name,affiliation:user.affiliation},csrf,needsProfile:isNewUser&&!user.full_name})}catch(error){await client.query('ROLLBACK');next(error)}finally{client.release()}});
app.get('/api/account/session',async(req,res,next)=>{try{const session=await customerSession(req);if(!session)return res.status(401).json({error:'No customer session.'});res.json({user:{id:session.user_id,phone:session.phone_e164,fullName:session.full_name,email:session.email,affiliation:session.affiliation,isHostelResident:session.is_hostel_resident,hostelId:session.hostel_id,roomNumber:session.room_number},csrf:session.csrf_hash})}catch(error){next(error)}});app.get('/api/account/wallet',requireCustomer,async(req,res,next)=>{try{res.json(await walletView(req.customer.user_id))}catch(error){next(error)}});
app.patch('/api/account/profile',requireCustomer,async(req,res,next)=>{try{const fullName=String(req.body.fullName||'').trim().slice(0,100),affiliation=req.body.affiliation,allowed=['student','faculty_staff','alumni','visitor_other'];if(!fullName)return res.status(400).json({error:'Enter your full name.'});if(!allowed.includes(affiliation))return res.status(400).json({error:'Select a valid affiliation.'});const resident=affiliation==='student'&&req.body.isHostelResident===true;if(resident&&!req.body.hostelId)return res.status(400).json({error:'Select your hostel.'});const result=await query(`UPDATE users SET full_name=$1,email=$2,affiliation=$3,is_hostel_resident=$4,hostel_id=$5,room_number=$6,updated_at=now() WHERE id=$7 RETURNING *`,[fullName,String(req.body.email||'').trim()||null,affiliation,resident,resident?req.body.hostelId:null,resident?String(req.body.roomNumber||'').slice(0,30):null,req.customer.user_id]);const user=result.rows[0];res.json({user:{id:user.id,phone:user.phone_e164,fullName:user.full_name,email:user.email,affiliation:user.affiliation,isHostelResident:user.is_hostel_resident,hostelId:user.hostel_id,roomNumber:user.room_number}})}catch(error){next(error)}});
