app.get('/api/account/orders',requireCustomer,async(req,res,next)=>{try{const result=await query(`SELECT o.*,COALESCE(jsonb_agg(jsonb_build_object('id',i.id,'productId',i.product_id,'name',i.product_name,'slug',i.slug,'sku',i.sku,'size',i.size,'color',i.color,'image',i.image,'quantity',i.quantity,'unitPrice',i.unit_price,'deliveredAt',i.delivered_at,'reviewed',r.id IS NOT NULL,'customization',CASE WHEN c.id IS NULL THEN NULL ELSE jsonb_build_object('text',c.custom_text,'placement',c.placement,'style',c.style,'color',c.text_color) END) ORDER BY i.created_at),'[]') items FROM orders o LEFT JOIN order_items i ON i.order_id=o.id LEFT JOIN reviews r ON r.order_item_id=i.id LEFT JOIN order_item_customizations c ON c.order_item_id=i.id WHERE o.user_id=$1 GROUP BY o.id ORDER BY o.created_at DESC`,[req.customer.user_id]);res.json({orders:result.rows})}catch(error){next(error)}});
